import {dimensionedComponent} from './verified-packages.mjs';
// Geometry supplied with OLIMEX's revision H project. Its scaled substitutions
// are preserved and reported, never represented as independently verified parts.
let cache=null,pending=null;
export async function loadManufacturerModels(){if(cache)return cache;if(pending)return pending;pending=(async()=>{const [manifest,placements]=await Promise.all(['manifest','placements'].map(n=>fetch('./models/'+n+'.json').then(r=>{if(!r.ok)throw Error('No se pudo cargar el catálogo CAD');return r.json();})));const models={};await Promise.all(Object.entries(manifest).map(async([name,record])=>{const r=await fetch('./models/'+record.asset);if(!r.ok)throw Error('No se pudo cargar '+name);const stream=new Blob([await r.arrayBuffer()]).stream().pipeThrough(new DecompressionStream('gzip'));models[name]=JSON.parse(await new Response(stream).text());}));cache={models,placements};return cache;})();try{return await pending;}catch(e){pending=null;throw e;}}
export function manufacturerComponent(T,el,group,pads=[]){if(dimensionedComponent(T,el,group,pads))return true;const placement=cache?.placements[el.name];if(!placement||!cache.models[placement.file]||el.assembly!=='fitted')return false;const frame=new T.Group();frame.position.set(el.x,el.y,el.mirror?-(el.boardThickness||1.25):0);frame.rotation.order='ZYX';frame.rotation.z=placement.angle*Math.PI/180;if(el.mirror)frame.rotation.x=Math.PI;group.add(frame);const model=new T.Group();model.position.fromArray(placement.offset);model.scale.fromArray(placement.scale);model.rotation.order='ZYX';model.rotation.set(...placement.rotate.map(x=>-x*Math.PI/180),'ZYX');frame.add(model);
for(const [i,data] of cache.models[placement.file].entries()){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(data.p,3));g.setIndex(data.ix);if(data.n)g.setAttribute('normal',new T.Float32BufferAttribute(data.n,3));else g.computeVertexNormals();const c=new T.Color(...(data.c||[.3,.3,.3]));const colors=new Float32Array(data.p.length);for(let j=0;j<colors.length;j+=3)c.toArray(colors,j);for(const f of data.faces||[]){const fc=new T.Color(...f.color);for(let j=f.first*3;j<(f.last+1)*3;j++)fc.toArray(colors,data.ix[j]*3);}g.setAttribute('color',new T.BufferAttribute(colors,3));const mesh=new T.Mesh(g,new T.MeshStandardMaterial({vertexColors:true,color:0xffffff,roughness:.48,metalness:.2}));mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData={component:el,manufacturer:true,sourceModel:placement.file,sourceScaled:placement.scaled};model.add(mesh);}return true;}
export function manufacturerStatus(){return cache;}
